// คิววอลเลย์บอล ไฟล์เดียวจบ (มีหน้าเว็บอยู่ในไฟล์นี้แล้ว) ใช้ Node.js 18 ขึ้นไป
// รัน: node queue.js   ตั้งรหัสผู้ดูแลด้วยตัวแปร ADMIN_PASSWORD (ถ้าไม่ตั้ง ทุกคนเป็นผู้ดูแล)
const http = require('http');
const fs = require('fs');
const path = require('path');
const os = require('os');
const crypto = require('crypto');

const PORT = Number(process.env.PORT) || 3000;
const ADMIN_PASSWORD = process.env.ADMIN_PASSWORD || '';
const DATA_FILE = path.join(__dirname, 'data.json');
const PAGE_HTML = Buffer.from('', 'base64');
const MAX_BODY = 64 * 1024;
const MAX_DOCS = 5000;
const PATH_RE = /^[A-Za-z0-9_\-.~:@+]{1,200}(\/[A-Za-z0-9_\-.~:@+]{1,200})*$/;

let docs = {};
try { docs = JSON.parse(fs.readFileSync(DATA_FILE, 'utf8')); } catch (e) { docs = {}; }

let saveTimer = null;
function save() {
  clearTimeout(saveTimer);
  saveTimer = setTimeout(() => {
    const tmp = DATA_FILE + '.tmp';
    fs.writeFile(tmp, JSON.stringify(docs), (err) => { if (!err) fs.rename(tmp, DATA_FILE, () => {}); });
  }, 200);
}

const clients = new Set();
function broadcastOnline() {
  const msg = 'event: online\ndata: ' + clients.size + '\n\n';
  clients.forEach((res) => res.write(msg));
}
function broadcast() {
  const msg = 'data: ' + JSON.stringify(docs) + '\n\n';
  clients.forEach((res) => res.write(msg));
}

/* ---- รหัสผ่านผู้ดูแล ---- */
const sha = (v) => crypto.createHash('sha256').update(v).digest();
const ADMIN_HASH = sha(ADMIN_PASSWORD);
const fails = new Map();
function clientIp(req) {
  const xf = req.headers['x-forwarded-for'];
  return (typeof xf === 'string' && xf.split(',')[0].trim()) || req.socket.remoteAddress || '?';
}
function limited(ip) {
  const f = fails.get(ip);
  if (!f) return false;
  if (Date.now() >= f.until) { fails.delete(ip); return false; }
  return f.n >= 8;
}
function noteFail(ip) {
  const f = fails.get(ip) || { n: 0, until: 0 };
  f.n += 1; f.until = Date.now() + 10 * 60 * 1000;
  fails.set(ip, f);
}
// คืนค่า 'ok' | 'none' (ไม่ได้ส่งรหัส) | 'bad' | 'limited'
function adminState(req) {
  if (!ADMIN_PASSWORD) return 'ok';
  const raw = req.headers['x-admin-password'];
  if (typeof raw !== 'string' || !raw) return 'none';
  const ip = clientIp(req);
  if (limited(ip)) return 'limited';
  let pw;
  try { pw = decodeURIComponent(raw); } catch (e) { pw = ''; }
  if (crypto.timingSafeEqual(sha(pw), ADMIN_HASH)) { fails.delete(ip); return 'ok'; }
  noteFail(ip);
  return 'bad';
}

/* ---- ตรวจคำสั่งเขียนข้อมูล ---- */
function validPath(p) {
  return typeof p === 'string' && PATH_RE.test(p) && p.split('/').length % 2 === 0;
}
function isPlain(o) { return o && typeof o === 'object' && !Array.isArray(o); }
function validOps(ops) {
  if (!Array.isArray(ops) || ops.length < 1 || ops.length > 50) return false;
  return ops.every((o) => o && validPath(o.path) &&
    (o.op === 'delete' || ((o.op === 'set' || o.op === 'update') && isPlain(o.data))));
}
var BAD = 'ควย,เหี้ย,เฮี้ย,สัส,ไอ้สัส,ส้นตีน,เย็ด,เงี่ยน,ชาติหมา,ระยำ,อีดอก,ดอกทอง,กระหรี่,อีสัตว์,ไอ้สัตว์,ไอ้เหี้ย,ไอ้ควาย,อีควาย,fuck,shit,bitch,dick,cunt,asshole,nigg,pussy,whore,slut'.split(',');
function normTxt(s) { return String(s).toLowerCase().replace(/[\u0E48-\u0E4C]/g, '').replace(/[^a-z0-9\u0E00-\u0E7F]/g, '').replace(/(.)\1+/g, '$1'); }
function hasBad(s, extra) { var n = normTxt(s); return BAD.concat(extra || []).some(function (w) { w = normTxt(w); return w && n.indexOf(w) !== -1; }); }
const EXTRA_BAD = (process.env.BANNED_WORDS || '').split(',').map((x) => x.trim()).filter(Boolean);
function validEntry(d, id) {
  return d.id === id && typeof d.name === 'string' && d.name.length >= 1 && d.name.length <= 60 && !hasBad(d.name, EXTRA_BAD) &&
    Number.isInteger(d.size) && d.size >= 1 && d.size <= 12 &&
    Array.isArray(d.pos) && d.pos.length <= 12 && d.pos.every((p) => typeof p === 'string' && p.length <= 4) &&
    typeof d.t === 'number' && typeof d.r === 'number' &&
    (d.court === undefined || d.court === 'F' || d.court === 'M');
}
// คนทั่วไปทำได้แค่: ลงชื่อใหม่ (สร้างอย่างเดียว) และอัปเดตคะแนน/เวลา
function allowedForPublic(ops) {
  return ops.every((o) => {
    const parts = o.path.split('/');
    if (parts[0] === 'match' && parts.length === 2 && ['F', 'M', 'main'].includes(parts[1]) && (o.op === 'set' || o.op === 'update')) return true;
    if (parts[0] === 'entries' && parts.length === 2 && o.op === 'set' && !(o.path in docs)) return validEntry(o.data, parts[1]);
    return false;
  });
}
function applyOps(ops) {
  for (const o of ops) {
    if (o.op === 'delete') delete docs[o.path];
    else if (o.op === 'set') docs[o.path] = o.data;
    else docs[o.path] = Object.assign({}, docs[o.path] || {}, o.data);
  }
  return Object.keys(docs).length <= MAX_DOCS;
}

function json(res, code, obj) {
  res.writeHead(code, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' });
  res.end(JSON.stringify(obj));
}

const server = http.createServer((req, res) => {
  const url = (req.url || '/').split('?')[0];

  if (req.method === 'GET' && url === '/api/events') {
    res.writeHead(200, {
      'Content-Type': 'text/event-stream', 'Cache-Control': 'no-cache, no-transform',
      Connection: 'keep-alive', 'X-Accel-Buffering': 'no'
    });
    res.write('retry: 2000\n\ndata: ' + JSON.stringify(docs) + '\n\n');
    clients.add(res);
    broadcastOnline();
    const beat = setInterval(() => res.write(': ping\n\n'), 25000);
    req.on('close', () => { clearInterval(beat); clients.delete(res); broadcastOnline(); });
    return;
  }

  if (req.method === 'GET' && url === '/api/state') return json(res, 200, docs);
  if (req.method === 'GET' && url === '/api/info') return json(res, 200, { adminRequired: !!ADMIN_PASSWORD });

  if (req.method === 'POST' && url === '/api/admin-check') {
    const st = adminState(req);
    if (st === 'ok') { res.writeHead(204); return res.end(); }
    res.writeHead(st === 'limited' ? 429 : 401); return res.end();
  }

  if (req.method === 'POST' && url === '/api/write') {
    const st = adminState(req);
    if (st === 'limited') { res.writeHead(429); return res.end(); }
    let size = 0;
    const chunks = [];
    req.on('data', (c) => {
      size += c.length;
      if (size > MAX_BODY) { res.writeHead(413); res.end(); req.destroy(); return; }
      chunks.push(c);
    });
    req.on('end', () => {
      let body;
      try { body = JSON.parse(Buffer.concat(chunks).toString('utf8')); } catch (e) { body = null; }
      if (!body || !validOps(body.ops)) { res.writeHead(400); return res.end('bad request'); }
      if (st !== 'ok' && !allowedForPublic(body.ops)) { res.writeHead(401); return res.end('admin required'); }
      if (!applyOps(body.ops)) { res.writeHead(400); return res.end('too many documents'); }
      save();
      broadcast();
      res.writeHead(204);
      res.end();
    });
    return;
  }

  if (req.method === 'GET' && (url === '/' || url === '/index.html')) {
    res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-cache' });
    return res.end(PAGE_HTML);
  }

  res.writeHead(404);
  res.end('not found');
});

server.listen(PORT, '0.0.0.0', () => {
  console.log('เซิร์ฟเวอร์คิววอลเลย์บอลทำงานแล้ว');
  console.log('  เครื่องนี้:   http://localhost:' + PORT);
  Object.values(os.networkInterfaces()).flat().forEach((i) => {
    if (i && i.family === 'IPv4' && !i.internal) console.log('  เครื่องอื่นใน Wi-Fi เดียวกัน: http://' + i.address + ':' + PORT);
  });
  console.log(ADMIN_PASSWORD ? 'รหัสผู้ดูแล: ตั้งไว้แล้ว' : 'คำเตือน: ยังไม่ได้ตั้ง ADMIN_PASSWORD ทุกคนจึงตั้งค่าและลบคิวได้');
});

process.on('SIGINT', () => {
  try { fs.writeFileSync(DATA_FILE, JSON.stringify(docs)); } catch (e) {}
  process.exit(0);
});
